#!/usr/bin/env Rscript
source('Figure/_shared/current.R')
source(file.path(module_dir,'style.R'));source(file.path(module_dir,'data.R'))
ids <- c('priority_score_distribution','regulatory_context_inset','hazard_exposure_landscape','score_decomposition','hazard_component_profiles','exposure_component_profiles')
for(id in ids) for(f in c('data.R','plot.R')) source(file.path(module_dir,'panels',id,f))
source(file.path(module_dir,'assemble.R'))
fields <- c('Inchikey_std','Priority_score','Priority_tier','Hazard_score','Exposure_score','GIC_regulatory_status',unname(hazard_components),unname(exposure_indicators))
compounds <- read_current(fields)
nums <- setdiff(fields,c('Inchikey_std','Priority_tier','GIC_regulatory_status'))
for(f in nums) compounds[[f]] <- strict_numeric(compounds[[f]],f)
stopifnot(sum(is.finite(compounds$Priority_score))==lock$ranked)
stopifnot(all(is.na(compounds$Priority_score)==(compounds$Priority_tier=='Insufficient evidence')))
compounds$GIC_regulatory_status_display <- unname(regulatory_status_map[compounds$GIC_regulatory_status])
stopifnot(!anyNA(compounds$GIC_regulatory_status_display))
metadata <- list(priority_score_min=min(compounds$Priority_score,na.rm=TRUE),priority_score_max=max(compounds$Priority_score,na.rm=TRUE),priority_score_median=median(compounds$Priority_score,na.rm=TRUE),priority_tier_counts=as.list(table(compounds$Priority_tier)),hazard_score_max=max(compounds$Hazard_score,na.rm=TRUE),exposure_score_max=max(compounds$Exposure_score,na.rm=TRUE))
prepared <- list(priority_score_distribution=prepare_priority_score_distribution(compounds,metadata),regulatory_context_inset=prepare_regulatory_context_inset(compounds),hazard_exposure_landscape=prepare_hazard_exposure_landscape(compounds,metadata,config),score_decomposition=prepare_score_decomposition(compounds),hazard_component_profiles=prepare_hazard_component_profiles(compounds),exposure_component_profiles=prepare_exposure_component_profiles(compounds,metadata))
plots <- list()
for(id in ids) {
 save_nested(prepared[[id]]$source_data,paste0(id,'/'))
 plots[[id]] <- get(paste0('plot_',id))(prepared[[id]]$source_data,config,'publication')
}
save_table(compounds,'compound_values')
save_facts(list(population=lock$total,ranked=lock$ranked,insufficient=lock$total-lock$ranked,panel_statistics=lapply(prepared,`[[`,'statistics'),missing='Full-inventory profiles distinguish unknown from zero; total-score panels require complete hazard and exposure.'))
save_plot(assemble_priority_landscape(plots,config),183,215)
